{
  "facts": [
    {
      "topic": "scope",
      "statement": "The entry creates compression and decompression contexts, compresses with ZSTD_compressStream2, then checks streaming and in-place decompression against the input.",
      "evidence": [
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 156, "end_line": 205, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 69, "end_line": 135, "role": "dependency", "dependency_reason": "These are the entry's streaming compression calls."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both source versions, ZSTD_CCtx_loadDictionary accepts a dictionary pointer and size and delegates to the advanced loader with by-copy and automatic content type.",
      "evidence": [
        {"unit_id": "u-74113fb17cc3741c936a", "start_line": 1308, "end_line": 1312, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-70b273cbea27885f3734", "start_line": 1308, "end_line": 1312, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "After-source ZSTD_compressStream2 delegates initialization to ZSTD_CCtx_init_compressStream2 when the context is at its initial stream stage. The supplied body does not show how that initializer handles a loaded dictionary.",
      "evidence": [
        {"unit_id": "u-8701eeeda36b1074f936", "start_line": 6285, "end_line": 6307, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "After-source sequence building derives dictMode from match state and passes it to ZSTD_selectBlockCompressor on the ordinary software path and on sequence-producer fallback. The selector contains separate dictionary-mode compressor tables.",
      "evidence": [
        {"unit_id": "u-e47bbab13fc8d06f6025", "start_line": 3235, "end_line": 3237, "role": "dependency", "dependency_reason": "Sequence building obtains dictionary mode from match state."},
        {"unit_id": "u-e47bbab13fc8d06f6025", "start_line": 3330, "end_line": 3355, "role": "dependency", "dependency_reason": "Fallback and ordinary software compression pass that mode to the selector."},
        {"unit_id": "u-0adc4df26dbe6bc8986a", "start_line": 3032, "end_line": 3114, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "After-source parameter adjustment cascades strategies downward when compressor exclusion macros are defined. The supplied build script delegates the build to fuzz.py; it does not itself establish which exclusion macros the build uses.",
      "evidence": [
        {"unit_id": "u-31b9fce4fcddd0beca8e", "start_line": 1470, "end_line": 1510, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-043cf5aa9ced10a35cb6", "start_line": 19, "end_line": 24, "role": "dependency", "dependency_reason": "The recipe invokes fuzz.py for the build."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The harness helper selects a strategy from ZSTD_STRATEGY_MIN through ZSTD_STRATEGY_MAX and can set dictionary-related parameters, including dedicated dictionary search and forceAttachDict. These parameter settings do not themselves supply dictionary bytes.",
      "evidence": [
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 44, "end_line": 56, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 101, "end_line": 110, "role": "dependency", "dependency_reason": "The selected strategy is applied to the compression context."},
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 138, "end_line": 145, "role": "dependency", "dependency_reason": "These are the dictionary-related parameter settings."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "Session-only reset does not take the branch that clears dictionaries. Thus reset alone cannot refute a route using a dictionary previously loaded into the context.",
      "evidence": [
        {"unit_id": "u-298245ec31957998eed7", "start_line": 1354, "end_line": 1369, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 63, "end_line": 65, "role": "dependency", "dependency_reason": "The harness uses session-only reset before compression."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The helper can register a sequence producer, and the after-source sequence builder can use it or fall back to the software compressor. This is an alternate compression route to account for when assessing selector reachability.",
      "evidence": [
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 77, "end_line": 99, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 156, "end_line": 164, "role": "dependency", "dependency_reason": "The helper conditionally enables or disables the producer."},
        {"unit_id": "u-e47bbab13fc8d06f6025", "start_line": 3286, "end_line": 3355, "role": "dependency", "dependency_reason": "Sequence building handles producer output, fallback, and the ordinary selector path."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "Across the complete old entry and its complete parameter helper, no call loads or references a compression dictionary. The entry's input bytes are divided between compression data and parameter generation, so those bytes cannot select a dictionary-loading call in this target.",
      "evidence": [
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 59, "end_line": 137, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 156, "end_line": 217, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 101, "end_line": 165, "role": "dependency", "dependency_reason": "This is the complete body of the entry's parameter-setting helper; it contains parameter and sequence-producer setup but no dictionary load."}
      ],
      "absence_claim": true,
      "audited_unit_ids": ["u-9dc9e88ae722c8cbe085", "u-194debf8ea4cd55b47ba"]
    },
    {
      "topic": "counterevidence",
      "statement": "The after-source dictionary-content loader has dictionary table paths, but returns before filling them when srcSize is at most HASH_READ_SIZE; its strategy cases also depend on exclusion macros. These conditions limit what the loader body alone establishes about the frozen streaming route.",
      "evidence": [
        {"unit_id": "u-69f78c39a8351db82eba", "start_line": 4805, "end_line": 4824, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-69f78c39a8351db82eba", "start_line": 4826, "end_line": 4865, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "The after-source ZSTD_CCtx_loadDictionary_advanced and ZSTD_CCtx_init_compressStream2 bodies are needed to establish whether a dictionary loaded through the public context setup reaches streaming initialization.",
    "The delegated fuzz.py build configuration and library defaults are needed to fix compressor exclusion macros for this target."
  ],
  "requested_symbols": ["ZSTD_CCtx_loadDictionary_advanced", "ZSTD_CCtx_init_compressStream2", "ZSTD_CCtx_refCDict"],
  "requested_paths": ["tests/fuzz/fuzz.py", "tests/fuzz/Makefile", "lib/libzstd.mk"]
}
